import React from "react";
import { useNavigate } from "react-router-dom";
import {
  FaJava,
  FaPython,
  FaDatabase,
  FaChartLine,
  FaLaptopCode,
  FaReact,
   FaEnvelope,
  FaLinkedin,
  FaGithub
} from "react-icons/fa";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">
      <div className="container">

        {/* LEFT SIDE */}
    {/* LEFT SIDE */}
{/* LEFT SIDE */}
<div className="left modern">

  {/* STATUS */}
  <div className="topLine">
    <span className="dot"></span>
    AVAILABLE FOR OPPORTUNITIES
  </div>

  {/* TITLE (clean + smaller) */}
  <h1 className="title">
    Hi, I'm{" "}
    <span className="nameGradient">Swetha A</span>
  </h1>

  {/* TAGS */}
  <div className="chips">
    <span>Software Developer</span>
    <span>UI Explorer</span>
    <span>Tech Enthusiast</span>
  </div>

  {/* DESCRIPTION */}
  <p className="desc">
    I design and build high-performance web applications with clean architecture,
    modern UI systems, and strong backend logic. I focus on creating scalable
    digital experiences that feel fast, intuitive, and impactful.
  </p>

  {/* BUTTONS */}
  <div className="buttons">
    <button className="btn primary" onClick={() => navigate("/projects")}>
      View My Work
    </button>

    <button className="btn secondary" onClick={() => navigate("/about")}>
      About Me
    </button>
  </div>

  {/* SOCIAL ICONS (REAL ICONS) */}
  <div className="socials">

    <a
  href="https://mail.google.com/mail/?view=cm&fs=1&to=swethaa1805@gmail.com"
  target="_blank"
  rel="noopener noreferrer"
>
  <FaEnvelope />
</a>

    <a href="https://www.linkedin.com/in/swetha-a-0b1712382/" target="_blank">
      <FaLinkedin />
    </a>

    <a href="https://github.com/Swethaa1805" target="_blank">
      <FaGithub />
    </a>

  </div>

</div>
        {/* RIGHT SIDE */}
        <div className="right">
          <div className="radar">

            {/* GLOW */}
            <div className="glow"></div>

            {/* RINGS */}
            <div className="ring r1"></div>
            <div className="ring r2"></div>
            <div className="ring r3"></div>

            {/* SCAN */}
            <div className="sweep"></div>

            {/* CENTER GIRL WITH LAPTOP */}
            <div className="center">
              <img
                src="https://cdn-icons-png.flaticon.com/512/3893/3893079.png"
                alt="girl working on laptop"
              />
            </div>

            {/* ORBIT ICONS */}
            <div className="orbit o1"><FaJava /></div>
            <div className="orbit o2"><FaPython /></div>
            <div className="orbit o3"><FaDatabase /></div>
            <div className="orbit o4"><FaChartLine /></div>
            <div className="orbit o5"><FaLaptopCode /></div>

            {/* NEW REACT ICON */}
            <div className="orbit o6"><FaReact /></div>

            {/* PARTICLES */}
            <span className="particle p1"></span>
            <span className="particle p2"></span>
            <span className="particle p3"></span>
            <span className="particle p4"></span>
            <span className="particle p5"></span>
            <span className="particle p6"></span>

          </div>
        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 6%;
        }

        .container {
  display: grid;
  grid-template-columns: 1.2fr 1fr;

  gap: 60px;

  width: 100%;
  align-items: center;

  /* IMPORTANT: keeps both sides visually centered */
  justify-content: space-between;
}

       /* LEFT SIDE - CLEAN TYPOGRAPHY STYLE */

/* LEFT MODERN CLEAN STYLE */

/* LEFT MODERN */

.left.modern {
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 620px;
  padding-top: -80px;
  padding-left:30px;
}

/* STATUS */
.topLine {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  letter-spacing: 2px;
  color: #94a3b8;
  margin-bottom: 14px;
}

.topLine .dot {
  width: 8px;
  height: 8px;
  background: #38BDF8;
  border-radius: 50%;
  box-shadow: 0 0 10px #38BDF8;
}

/* TITLE (smaller + cleaner) */
.title {
  font-family: "Space Grotesk", sans-serif;
  font-size: 44px;
  font-weight: 600;
  color: #e2e8f0;
  letter-spacing: -0.5px;
  line-height: 1.2;
}

/* NAME (SPECIAL PREMIUM STYLE) */
.nameGradient {
  font-family: "Space Grotesk", sans-serif;
  font-weight: 700;

  background: linear-gradient(90deg, #38BDF8, #60a5fa);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;

  letter-spacing: -0.5px;
}

/* TAG CHIPS */
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.chips span {
